def backfill_report_image_evidence(apps, schema_editor):
    Report = apps.get_model("market", "Report")
    Evidence = apps.get_model("market", "ReportImageEvidence")
    Evidence.objects.bulk_create(
        [
            Evidence(
                report_id=report.pk,
                storage_name=report.listing_image_name_snapshot,
                sha256=report.listing_image_sha256,
                position=0,
            )
            for report in Report.objects.exclude(listing_image_name_snapshot="").iterator()
        ],
        ignore_conflicts=True,
    )


def remove_backfilled_report_image_evidence(apps, schema_editor):
    Evidence = apps.get_model("market", "ReportImageEvidence")
    Evidence.objects.filter(position=0).delete()


